import React, { useState } from 'react';

export default function RestaurantBooking() {
  const [formData, setFormData] = useState({
    location: '',
    cuisine: '',
    date: '',
    time: '',
    partySize: ''
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      // محاكاة تأخير الشبكة
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      console.log('البحث عن:', formData);
      setMessage('تم العثور على طاولات متاحة! سيتم توجيهك لصفحة النتائج...');
      
    } catch (error) {
      console.error('خطأ في البحث:', error);
      setMessage('حدث خطأ أثناء البحث. يرجى المحاولة مرة أخرى.');
    } finally {
      setLoading(false);
    }
  };

  const styles = {
    container: {
      position: 'relative',
      minHeight: '100vh',
      overflow: 'hidden',
      background: `linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
                   radial-gradient(circle at 20% 30%, rgba(46, 125, 50, 0.4) 0%, transparent 50%),
                   radial-gradient(circle at 80% 20%, rgba(76, 175, 80, 0.4) 0%, transparent 50%),
                   radial-gradient(circle at 40% 70%, rgba(129, 199, 132, 0.3) 0%, transparent 50%),
                   radial-gradient(circle at 90% 80%, rgba(165, 214, 167, 0.3) 0%, transparent 50%),
                   linear-gradient(135deg, #1b5e20 0%, #2e7d32 50%, #388e3c 100%)`,
      backgroundSize: 'cover, cover, cover, cover, cover, cover'
    }
  };

  return (
    <div style={styles.container}>
      <style jsx>{`
        /* Bokeh Light Effects */
        .bokeh-light {
          position: absolute;
          border-radius: 50%;
          background: radial-gradient(circle, rgba(76, 175, 80, 0.8) 0%, rgba(129, 199, 132, 0.4) 100%);
          animation: pulse 3s ease-in-out infinite alternate;
          z-index: 2;
          pointer-events: none;
        }

        @keyframes pulse {
          0% { 
            opacity: 0.4; 
            transform: scale(1); 
          }
          100% { 
            opacity: 0.8; 
            transform: scale(1.2); 
          }
        }

        /* Glass Morphism Form */
        .glass-form {
          background: linear-gradient(135deg, 
            rgba(255, 255, 255, 0.15) 0%, 
            rgba(255, 255, 255, 0.05) 100%);
          backdrop-filter: blur(15px);
          -webkit-backdrop-filter: blur(15px);
          border: 1px solid rgba(255, 255, 255, 0.3);
          box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4),
                      0 0 0 1px rgba(255, 255, 255, 0.1) inset;
          border-radius: 1.5rem;
          padding: 2rem;
          max-width: 900px;
          width: 100%;
          margin: 0 auto;
        }

        /* Form Controls with Glass Effect */
        .form-control-glass {
          background: linear-gradient(135deg, 
            rgba(255, 255, 255, 0.2) 0%, 
            rgba(255, 255, 255, 0.1) 100%);
          border: 1px solid rgba(255, 255, 255, 0.4);
          color: white;
          backdrop-filter: blur(10px);
          -webkit-backdrop-filter: blur(10px);
          transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
          height: 58px;
          line-height: 1.5;
          padding: 0.5rem 1rem;
          font-size: 1.125rem;
          font-weight: 500;
          border-radius: 0.5rem;
          width: 100%;
        }

        .form-control-glass:focus {
          background: linear-gradient(135deg, 
            rgba(76, 175, 80, 0.3) 0%, 
            rgba(129, 199, 132, 0.2) 100%);
          border-color: #4caf50;
          box-shadow: 0 0 0 0.25rem rgba(76, 175, 80, 0.3),
                      0 0 20px rgba(76, 175, 80, 0.5);
          color: white;
          transform: translateY(-2px);
          outline: none;
        }

        .form-control-glass::placeholder {
          color: rgba(255, 255, 255, 0.8);
        }

        /* Search Button - Light Green Color */
        .btn-search {
          background: linear-gradient(135deg, #90EE90 0%, #98FB98 100%);
          border: none;
          font-weight: bold;
          text-transform: uppercase;
          letter-spacing: 2px;
          transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
          box-shadow: 0 8px 25px rgba(144, 238, 144, 0.4),
                      0 0 0 1px rgba(255, 255, 255, 0.2) inset;
          color: #1b5e20;
          position: relative;
          overflow: hidden;
          border-radius: 0.5rem;
          height: 58px;
          width: 100%;
          font-size: 1.125rem;
          cursor: pointer;
        }

        .btn-search::before {
          content: '';
          position: absolute;
          top: 0;
          left: -100%;
          width: 100%;
          height: 100%;
          background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
          transition: left 0.6s;
        }

        .btn-search:hover::before {
          left: 100%;
        }

        .btn-search:hover {
          transform: translateY(-3px) scale(1.02);
          box-shadow: 0 12px 35px rgba(144, 238, 144, 0.6),
                      0 0 30px rgba(152, 251, 152, 0.4);
          color: #1b5e20;
        }

        .btn-search:active {
          transform: translateY(-1px) scale(0.98);
        }

        .btn-search:disabled {
          opacity: 0.7;
          cursor: not-allowed;
          transform: none;
        }

        /* Title Styling - White Color */
        .title-glow {
          color: white;
          text-shadow: 0 0 30px rgba(255, 255, 255, 0.6),
                       0 0 60px rgba(255, 255, 255, 0.4),
                       0 0 90px rgba(255, 255, 255, 0.3);
          font-family: 'Georgia', serif;
          font-weight: 900;
          font-size: 4rem;
          letter-spacing: 3px;
          text-align: center;
          margin-bottom: 2rem;
        }

        /* Wine Glass Decoration */
        .wine-glass {
          width: 35px;
          height: 70px;
          background: linear-gradient(to top, 
            rgba(76, 175, 80, 0.3) 0%, 
            rgba(129, 199, 132, 0.2) 50%,
            transparent 100%);
          border-radius: 17px 17px 0 0;
          position: relative;
          opacity: 0.4;
          animation: float 4s ease-in-out infinite;
        }

        .wine-glass::after {
          content: '';
          position: absolute;
          bottom: -12px;
          left: 50%;
          transform: translateX(-50%);
          width: 45px;
          height: 12px;
          background: linear-gradient(135deg, rgba(76, 175, 80, 0.2), rgba(129, 199, 132, 0.2));
          border-radius: 6px;
        }

        .wine-glass::before {
          content: '';
          position: absolute;
          bottom: -18px;
          left: 50%;
          transform: translateX(-50%);
          width: 55px;
          height: 10px;
          background: linear-gradient(135deg, rgba(129, 199, 132, 0.2), rgba(165, 214, 167, 0.2));
          border-radius: 0 0 12px 12px;
        }

        @keyframes float {
          0%, 100% { 
            transform: translateY(0px) rotate(0deg); 
          }
          50% { 
            transform: translateY(-15px) rotate(2deg); 
          }
        }

        /* Form Labels - Black Color */
        .form-label {
          font-weight: 700;
          text-shadow: 0 2px 4px rgba(255, 255, 255, 0.8);
          margin-bottom: 0.75rem;
          color: black;
          font-size: 1.1rem;
        }

        /* Alert Styling */
        .alert {
          backdrop-filter: blur(15px);
          -webkit-backdrop-filter: blur(15px);
          border: none;
          font-weight: 600;
          border-radius: 0.75rem;
          margin-bottom: 1.5rem;
          padding: 1rem;
        }

        .alert-success {
          background: linear-gradient(135deg, 
            rgba(76, 175, 80, 0.3) 0%, 
            rgba(129, 199, 132, 0.2) 100%);
          color: #d4edda;
          border: 1px solid rgba(76, 175, 80, 0.4);
        }

        .alert-danger {
          background: linear-gradient(135deg, 
            rgba(220, 53, 69, 0.3) 0%, 
            rgba(233, 69, 96, 0.2) 100%);
          color: #f8d7da;
          border: 1px solid rgba(220, 53, 69, 0.4);
        }

        /* Decorative animations */
        .decoration-square {
          animation: rotate 10s linear infinite;
        }

        .decoration-circle {
          animation: bounce 3s ease-in-out infinite;
        }

        @keyframes rotate {
          from { transform: rotate(45deg); }
          to { transform: rotate(405deg); }
        }

        @keyframes bounce {
          0%, 100% { transform: translateY(0) scale(1); }
          50% { transform: translateY(-8px) scale(1.1); }
        }

        /* Main content container */
        .main-content {
          position: relative;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          min-height: 100vh;
          padding: 1rem;
          z-index: 10;
        }

        /* Grid layout */
        .form-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
          gap: 1.5rem;
          width: 100%;
        }

        .form-group {
          display: flex;
          flex-direction: column;
        }

        .button-group {
          display: flex;
          align-items: end;
        }

        /* Responsive Design */
        @media (max-width: 768px) {
          .title-glow {
            font-size: 3rem;
            letter-spacing: 2px;
          }
          
          .glass-form {
            margin: 1rem;
            padding: 1.5rem;
          }
          
          .wine-glass {
            width: 25px;
            height: 50px;
          }

          .form-grid {
            grid-template-columns: 1fr;
            gap: 1rem;
          }
        }

        @media (max-width: 576px) {
          .title-glow {
            font-size: 2.5rem;
            letter-spacing: 1px;
          }
          
          .glass-form {
            padding: 1rem;
          }
        }

        /* Loading Spinner */
        .spinner {
          width: 1rem;
          height: 1rem;
          border: 2px solid transparent;
          border-top: 2px solid currentColor;
          border-radius: 50%;
          animation: spin 1s linear infinite;
          display: inline-block;
          margin-right: 0.5rem;
        }

        @keyframes spin {
          to { transform: rotate(360deg); }
        }

        /* Wine glasses container */
        .wine-glasses-container {
          position: absolute;
          bottom: 0;
          left: 0;
          width: 100%;
          height: 120px;
          z-index: 3;
          display: flex;
          justify-content: space-around;
          align-items: end;
          padding: 0 3rem;
        }

        /* Decorative elements positioning */
        .decorative-elements {
          position: absolute;
          top: 0;
          left: 0;
          width: 100%;
          height: 100%;
          pointer-events: none;
          z-index: 4;
        }

        .decoration-1 { top: 80px; left: 40px; width: 20px; height: 20px; border: 2px solid #4caf50; transform: rotate(45deg); opacity: 0.4; position: absolute; }
        .decoration-2 { top: 160px; right: 80px; width: 15px; height: 15px; background: linear-gradient(135deg, #81c784, #a5d6a7); opacity: 0.5; border-radius: 50%; position: absolute; }
        .decoration-3 { bottom: 120px; left: 80px; width: 25px; height: 25px; border: 2px solid #a5d6a7; opacity: 0.4; border-radius: 50%; position: absolute; }
        .decoration-4 { bottom: 80px; right: 40px; width: 18px; height: 18px; background: linear-gradient(135deg, #c8e6c9, #4caf50); transform: rotate(45deg); opacity: 0.5; position: absolute; }

        .title-underline {
          width: 120px;
          height: 3px;
          background: linear-gradient(135deg, #4caf50, #81c784);
          opacity: 0.9;
          border-radius: 2px;
          margin: 0 auto 3rem auto;
        }
      `}</style>

      {/* Animated bokeh lights */}
      {[...Array(8)].map((_, i) => (
        <div
          key={i}
          className="bokeh-light"
          style={{
            width: Math.random() * 25 + 10 + 'px',
            height: Math.random() * 25 + 10 + 'px',
            left: Math.random() * 100 + '%',
            top: Math.random() * 100 + '%',
            animationDelay: Math.random() * 2 + 's',
            animationDuration: (Math.random() * 2 + 2) + 's'
          }}
        />
      ))}

      {/* Wine glasses decoration */}
      <div className="wine-glasses-container">
        {[...Array(6)].map((_, i) => (
          <div key={i} className="wine-glass" style={{animationDelay: i * 0.5 + 's'}}></div>
        ))}
      </div>

      {/* Decorative Elements */}
      <div className="decorative-elements">
        <div className="decoration-1 decoration-square"></div>
        <div className="decoration-2 decoration-circle"></div>
        <div className="decoration-3 decoration-circle"></div>
        <div className="decoration-4 decoration-square"></div>
      </div>

      {/* Main Content */}
      <div className="main-content">
        
        {/* Title */}
        <div>
          <h1 className="title-glow">
            BOOK A TABLE
          </h1>
          <div className="title-underline"></div>
        </div>

        {/* Booking Form */}
        <div className="glass-form">
          {message && (
            <div className={`alert ${message.includes('خطأ') ? 'alert-danger' : 'alert-success'}`}>
              {message}
            </div>
          )}
          
          <div>
            <div className="form-grid">
              {/* Location */}
              <div className="form-group">
                <label htmlFor="location" className="form-label">
                  Location:
                </label>
                <input
                  type="text"
                  className="form-control-glass"
                  id="location"
                  name="location"
                  value={formData.location}
                  onChange={handleInputChange}
                  placeholder="اختر الموقع"
                  required
                />
              </div>
              
              {/* Cuisine */}
              <div className="form-group">
                <label htmlFor="cuisine" className="form-label">
                  Cuisine:
                </label>
                <input
                  type="text"
                  className="form-control-glass"
                  id="cuisine"
                  name="cuisine"
                  value={formData.cuisine}
                  onChange={handleInputChange}
                  placeholder="أدخل نوع المطبخ"
                  required
                />
              </div>

              {/* Date */}
              <div className="form-group">
                <label htmlFor="date" className="form-label">
                  Date:
                </label>
                <input
                  type="date"
                  className="form-control-glass"
                  id="date"
                  name="date"
                  value={formData.date}
                  onChange={handleInputChange}
                  min={new Date().toISOString().split('T')[0]}
                  required
                />
              </div>

              {/* Time */}
              <div className="form-group">
                <label htmlFor="time" className="form-label">
                  Time:
                </label>
                <input
                  type="time"
                  className="form-control-glass"
                  id="time"
                  name="time"
                  value={formData.time}
                  onChange={handleInputChange}
                  required
                />
              </div>

              {/* Party Size */}
              <div className="form-group">
                <label htmlFor="partySize" className="form-label">
                  Party Size:
                </label>
                <input
                  type="number"
                  className="form-control-glass"
                  id="partySize"
                  name="partySize"
                  value={formData.partySize}
                  onChange={handleInputChange}
                  placeholder="عدد الأشخاص"
                  min="1"
                  max="20"
                  required
                />
              </div>

              {/* Search Button */}
              <div className="button-group">
                <button
                  type="submit"
                  className="btn-search"
                  disabled={loading}
                  onClick={handleSearch}
                >
                  {loading ? (
                    <>
                      <span className="spinner"></span>
                      Searching...
                    </>
                  ) : (
                    'SEARCH'
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
